"use strict";

const path = require("node:path");

const LATHE_TOOL_TYPES = [
  "external-cutter",
  "internal-cutter",
  "drill",
  "groove",
  "cutoff",
  "threading",
  "tap",
  "reamer",
  "bar-puller",
  "non-cutting",
  "other"
];

const MILL_TOOL_TYPES = [
  "end-mill",
  "ball-mill",
  "bull-nose-mill",
  "face-mill",
  "chamfer-mill",
  "slot-mill",
  "thread-mill",
  "engraver",
  "drill",
  "spot-drill",
  "center-drill",
  "tap",
  "reamer",
  "boring-head",
  "probe",
  "other"
];

const TOOL_TYPES = new Set([...LATHE_TOOL_TYPES, ...MILL_TOOL_TYPES]);

const TOOL_HANDS = new Set(["left", "right", "neutral", "unknown"]);
const RECOGNITION_SOURCES = new Set(["manual", "ai", "heuristic"]);

function decodeXml(value) {
  return String(value || "")
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&amp;/g, "&");
}

function encodeXml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/"/g, "&quot;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function attributes(source) {
  const result = {};
  const expression = /([A-Za-z_:][\w:.-]*)\s*=\s*"([^"]*)"/g;
  let match;
  while ((match = expression.exec(source)) !== null) {
    result[match[1]] = decodeXml(match[2]);
  }
  return result;
}

function parseToolTable(xml) {
  const rootMatch = xml.match(/<toolTable\b([^>]*)>/i);
  if (!rootMatch) {
    throw new Error("toolTable root element was not found");
  }
  const root = attributes(rootMatch[1]);
  const table = {
    schemaVersion: root.schemaVersion || "1.0",
    name: root.name || "Unnamed tool table",
    units: root.units || "mm",
    autoGenerated: String(root.autoGenerated || "").toLowerCase() === "true",
    tools: {}
  };

  const toolExpression = /<tool\b([^>]*?)\/>/gi;
  let match;
  while ((match = toolExpression.exec(xml)) !== null) {
    const definition = attributes(match[1]);
    const number = Number(definition.number);
    const cornerRadius = Number(definition.cornerRadius);
    const tip = Number(definition.tip);
    const type = String(definition.type || "").trim().toLowerCase();
    const diameter = definition.diameter === undefined
      ? undefined
      : Number(definition.diameter);
    const width = definition.width === undefined
      ? undefined
      : Number(definition.width);
    const length = definition.length === undefined
      ? undefined
      : Number(definition.length);
    const confidence = definition.confidence === undefined
      ? undefined
      : Number(definition.confidence);
    const hand = String(definition.hand || "unknown").trim().toLowerCase();
    const recognition = String(
      definition.recognition || (table.autoGenerated ? "heuristic" : "manual")
    ).trim().toLowerCase();
    const locked = String(definition.locked || "").toLowerCase() === "true";
    const tipKnown = definition.tipKnown === undefined
      ? recognition === "manual"
      : String(definition.tipKnown).toLowerCase() !== "false";

    if (!Number.isInteger(number) || number < 1 || number > 999) {
      throw new Error(`Invalid tool number "${definition.number || ""}"`);
    }
    if (table.tools[number]) {
      throw new Error(`Tool T${number} is defined more than once`);
    }
    if (!Number.isFinite(cornerRadius) || cornerRadius < 0) {
      throw new Error(`Tool T${number} has invalid cornerRadius "${definition.cornerRadius || ""}"`);
    }
    if (!Number.isInteger(tip) || tip < 0 || tip > 9) {
      throw new Error(`Tool T${number} has invalid tip "${definition.tip || ""}"; expected 0 through 9`);
    }
    if (!TOOL_TYPES.has(type)) {
      throw new Error(
        `Tool T${number} has unsupported type "${definition.type || ""}"`
      );
    }
    if (diameter !== undefined && (!Number.isFinite(diameter) || diameter < 0)) {
      throw new Error(`Tool T${number} has invalid diameter "${definition.diameter}"`);
    }
    if (width !== undefined && (!Number.isFinite(width) || width < 0)) {
      throw new Error(`Tool T${number} has invalid width "${definition.width}"`);
    }
    if (length !== undefined && (!Number.isFinite(length) || length < 0)) {
      throw new Error(`Tool T${number} has invalid length "${definition.length}"`);
    }
    if (confidence !== undefined &&
        (!Number.isFinite(confidence) || confidence < 0 || confidence > 1)) {
      throw new Error(`Tool T${number} has invalid confidence "${definition.confidence}"`);
    }
    if (!TOOL_HANDS.has(hand)) {
      throw new Error(`Tool T${number} has unsupported hand "${definition.hand}"`);
    }
    if (!RECOGNITION_SOURCES.has(recognition)) {
      throw new Error(
        `Tool T${number} has unsupported recognition "${definition.recognition}"`
      );
    }

    table.tools[number] = {
      number,
      cornerRadius,
      tip,
      type,
      description: definition.description || "",
      diameter,
      width,
      length,
      hand,
      confidence,
      recognition,
      evidence: definition.evidence || "",
      locked,
      tipKnown
    };
  }

  return table;
}

function relatedToolTablePaths(documentFileName) {
  const directory = path.dirname(documentFileName);
  const extension = path.extname(documentFileName);
  const stem = path.basename(documentFileName, extension);
  return [
    path.join(directory, `${stem}.tools.xml`),
    path.join(directory, `${stem}.tool-table.xml`)
  ];
}

function serializeToolTable(table, sourceGcode = "") {
  const tools = Object.values(table?.tools || {}).sort(
    (a, b) => Number(a.number) - Number(b.number)
  );
  const sourceAttribute = sourceGcode
    ? `\n  sourceGcode="${encodeXml(sourceGcode)}"`
    : "";
  const autoGenerated = table?.autoGenerated !== false;
  const lines = [
    '<?xml version="1.0" encoding="UTF-8"?>',
    '<toolTable',
    `  schemaVersion="${encodeXml(table?.schemaVersion || "1.0")}"`,
    `  name="${encodeXml(table?.name || "Generated tool table")}"`,
    `  units="${encodeXml(table?.units || "mm")}"${sourceAttribute}`,
    `  autoGenerated="${autoGenerated}">`,
    "",
    autoGenerated
      ? "  <!-- Automatically synchronized from the related NC program."
      : "  <!-- Manually edited for the related NC program.",
    "       Existing values are retained for tools that remain in the program. -->"
  ];
  for (const tool of tools) {
    const optionalAttributes = [];
    if (Number.isFinite(tool.diameter)) {
      optionalAttributes.push(`diameter="${Number(tool.diameter)}"`);
    }
    if (Number.isFinite(tool.width)) {
      optionalAttributes.push(`width="${Number(tool.width)}"`);
    }
    if (Number.isFinite(tool.length)) {
      optionalAttributes.push(`length="${Number(tool.length)}"`);
    }
    if (TOOL_HANDS.has(tool.hand)) {
      optionalAttributes.push(`hand="${encodeXml(tool.hand)}"`);
    }
    if (Number.isFinite(tool.confidence)) {
      optionalAttributes.push(`confidence="${Number(tool.confidence).toFixed(3)}"`);
    }
    if (RECOGNITION_SOURCES.has(tool.recognition)) {
      optionalAttributes.push(`recognition="${encodeXml(tool.recognition)}"`);
    }
    if (tool.locked) {
      optionalAttributes.push('locked="true"');
    }
    if (tool.tipKnown === false) {
      optionalAttributes.push('tipKnown="false"');
    }
    lines.push(
      `  <tool number="${Number(tool.number)}" cornerRadius="${Number(tool.cornerRadius) || 0}" tip="${Number(tool.tip) || 0}" type="${encodeXml(tool.type || "other")}"`,
      `    description="${encodeXml(tool.description || "")}"${optionalAttributes.length ? ` ${optionalAttributes.join(" ")}` : ""}`,
      `    evidence="${encodeXml(tool.evidence || "")}" />`
    );
  }
  lines.push("</toolTable>", "");
  return lines.join("\n");
}

module.exports = {
  LATHE_TOOL_TYPES,
  MILL_TOOL_TYPES,
  RECOGNITION_SOURCES,
  TOOL_HANDS,
  TOOL_TYPES,
  parseToolTable,
  relatedToolTablePaths,
  serializeToolTable
};
